def lcs_len(a, b):
    if len(a) < len(b):
        a, b = b, a

    dp = [0] * (len(b) + 1)

    for x in a:
        prev = 0
        for j, y in enumerate(b, 1):
            temp = dp[j]
            if x == y:
                dp[j] = prev + 1
            elif dp[j - 1] > dp[j]:
                dp[j] = dp[j - 1]
            prev = temp

    return dp[-1]

