def normalize(path):
    absolute = path.startswith('/')
    stack = []

    for part in path.split('/'):
        if not part or part == '.':
            continue
        if part == '..':
            if stack and stack[-1] != '..':
                stack.pop()
            elif not absolute:
                stack.append('..')
        else:
            stack.append(part)

    if absolute:
        return '/' + '/'.join(stack) if stack else '/'
    return '/'.join(stack) if stack else '.'

