def parse_duration(s: str) -> int:
    import re

    if not isinstance(s, str):
        raise ValueError("Input must be a string")

    text = s.strip()
    full_pattern = r"(?:\s*[0-9]+\s*[dhms]\s*)+"

    if not re.fullmatch(full_pattern, text, re.IGNORECASE):
        raise ValueError("Invalid duration format")

    unit_seconds = {
        "d": 86400,
        "h": 3600,
        "m": 60,
        "s": 1,
    }

    total = 0
    for match in re.finditer(r"([0-9]+)\s*([dhms])", text, re.IGNORECASE):
        total += int(match.group(1)) * unit_seconds[match.group(2).lower()]

    return total

