def validate_ipv4(s):
    if not isinstance(s, str):
        return False

    parts = s.split('.')
    if len(parts) != 4:
        return False

    for part in parts:
        if not part or not all(c in '0123456789' for c in part):
            return False
        if len(part) > 1 and part[0] == '0':
            return False
        if len(part) > 3 or int(part) > 255:
            return False

    return True

