def parse_ini(text):
    result = {}
    section = ""

    for raw_line in text.splitlines():
        line = raw_line.strip()

        if not line or line[0] in ";#":
            continue

        if line.startswith("[") and line.endswith("]"):
            section = line[1:-1].strip()
            result.setdefault(section, {})
            continue

        if "=" in line:
            key, _, value = line.partition("=")
        elif ":" in line:
            key, _, value = line.partition(":")
        else:
            continue

        key = key.strip()
        value = value.strip()
        result.setdefault(section, {})[key] = value

    return result

