def coin_change(coins, amount):
    if amount < 0:
        return -1

    dp = [amount + 1] * (amount + 1)
    dp[0] = 0

    for i in range(1, amount + 1):
        for coin in coins:
            if 0 < coin <= i and dp[i - coin] + 1 < dp[i]:
                dp[i] = dp[i - coin] + 1

    return -1 if dp[amount] == amount + 1 else dp[amount]

