function debounceCount(fn, ms) {
  let timer = null;
  let thisArg = undefined;
  let args = null;

  function run() {
    if (timer === null) return;
    clearTimeout(timer);
    timer = null;
    fn.apply(thisArg, args);
    thisArg = undefined;
    args = null;
  }

  const call = function (...a) {
    thisArg = this;
    args = a;
    if (timer !== null) clearTimeout(timer);
    timer = setTimeout(run, ms);
  };

  const flush = function () {
    run();
  };

  return { call, flush };
}

module.exports = debounceCount;

