function padLeft(s, n, ch = ' ') {
  s = String(s);
  n = Math.floor(Number(n));

  if (!Number.isFinite(n) || n <= s.length) {
    return s;
  }

  const padChar = String(ch);
  if (padChar.length === 0) {
    return s;
  }

  const needed = n - s.length;
  const pad = padChar.repeat(Math.ceil(needed / padChar.length));

  return pad.slice(0, needed) + s;
}

module.exports = padLeft;

