  const keys = Array.isArray(keyFns) ? keyFns : keyFns ? [keyFns] : [];
  const copy = arr.slice();

  copy.sort((a, b) => {
    for (const keyFn of keys) {
      const aKey = keyFn(a);
      const bKey = keyFn(b);

      if (aKey < bKey) return -1;
      if (bKey < aKey) return 1;
    }

