export class Emitter {
  private handlers = new Map<string, Handler[]>();

  on(t: string, h: Handler): void {
    const list = this.handlers.get(t);
    if (list) {
      list.push(h);
    } else {
      this.handlers.set(t, [h]);
    }
  }

  emit(t: string): void {
    const list = this.handlers.get(t);
