import React, { useCallback, useEffect, useState } from "react";
import { FlatList, StyleSheet, Text, View } from "react-native";

const PAGE_SIZE = 10;

const fetchData = async page => {
  await new Promise(resolve => setTimeout(resolve, 500));

  const start = (page - 1) * PAGE_SIZE;

  return Array.from({ length: PAGE_SIZE }, (_, index) => ({
    id: String(start + index + 1)
  }));
};

const InfiniteScrollFlatList = () => {
  const [data, setData] = useState([]);
  const [page, setPage] = useState(1);
  const [loading, setLoading] = useState(false);
  const [refreshing, setRefreshing] = useState(false);
  const [error, setError] = useState(null);

  const loadInitial = useCallback(async () => {
    setLoading(true);
    setError(null);

    try {
      const items = await fetchData(1);
      setData(items);
      setPage(1);
    } catch (err) {
      setError(err);
    } finally {
      setLoading(false);
    }
  }, []);

  const onEndReached = useCallback(async () => {
    if (loading || error) {
      return;
    }

    setLoading(true);
    setError(null);

    try {
      const items = await fetchData(page + 1);
      setData(previous => [...previous, ...items]);
      setPage(previous => previous + 1);
    } catch (err) {
      setError(err);
    } finally {
      setLoading(false);
    }
  }, [loading, error, page]);

  const onRefresh = useCallback(async () => {
    setRefreshing(true);
    await loadInitial();
    setRefreshing(false);
  }, [loadInitial]);

  useEffect(() => {
    loadInitial();
  }, [loadInitial]);

  return (
    <FlatList
      data={data}
      keyExtractor={item => item.id}
      renderItem={({ item }) => (
        <View style={styles.row}>
          <Text>Item {item.id}</Text>
        </View>
      )}
      onEndReached={onEndReached}
      onEndReachedThreshold={0.5}
      onRefresh={onRefresh}
      refreshing={refreshing}
      ListEmptyComponent={
        loading ? (
          <Text style={styles.footerText}>Loading...</Text>
        ) : error ? (
          <Text style={styles.footerText}>Failed to load data.</Text>
        ) : null
      }
      ListFooterComponent={
        error ? (
          <Text style={styles.footerText}>Failed to load more.</Text>
        ) : loading ? (
          <Text style={styles.footerText}>Loading...</Text>
        ) : null
      }
      contentContainerStyle={styles.content}
      keyboardShouldPersistTaps="handled"
    />
  );
};

const styles = StyleSheet.create({
  content: {
    paddingVertical: 8
  },
  row: {
    paddingHorizontal: 16,
    paddingVertical: 12,
    borderBottomWidth: 1,
    borderBottomColor: "#ccc"
  },
  footerText: {
    textAlign: "center",
    padding: 16,
    color: "#888"
  }
});

export default InfiniteScrollFlatList;

