import React from 'react';
import { View, Text } from 'react-native';

type Props = {
  showFirst: boolean;
};

const ConditionalView = ({ showFirst }: Props) => {
  return showFirst ? (
    <View style={{ padding: 16 }}>
      <Text>First View</Text>
    </View>
  ) : (
    <View style={{ padding: 16 }}>
      <Text>Second View</Text>
    </View>
  );
};

export default ConditionalView;

