import React from 'react';
import { FlatList, Text } from 'react-native';

export default function MyFlatList({ data }) {
  return (
    <FlatList
      data={data}
      keyExtractor={(item, index) =>
        item?.id != null ? String(item.id) : String(index)
      }
      renderItem={({ item }) => <Text>{item.name}</Text>}
    />
  );
}

