import React, { useRef } from 'react';
import { View, Text, Pressable } from 'react-native';

export default function MutableValueComponent() {
  const valueRef = useRef(0);

  const increment = () => {
    valueRef.current += 1;
  };

  return (
    <View>
      <Text>{valueRef.current}</Text>
      <Pressable onPress={increment}>
        <Text>Increment</Text>
      </Pressable>
    </View>
  );
}

